#!/usr/bin/env python3
"""Apply the tested speed-only delta to the exact 4.6.4.1 integrated source.
The compressed line edits contain source text, not firmware. Every input/output
file is SHA-256 checked, all edits validated before writing, and a readable patch
is generated for review. No bootloader, clock, HAL, or library-reuse changes.
"""
from pathlib import Path
import base64, difflib, hashlib, json, lzma
R = Path(__file__).resolve().parents[1]
DATA = ''''''
blob = base64.b64decode(DATA, validate=True)
assert hashlib.sha256(blob).hexdigest() == '73857b17608c601b5f83dce6cfe3ea9148dede4d873ec91887404543a9d2e6df'
data = json.loads(lzma.decompress(blob))
pending = {}; patch = ''
for name, spec in data.items():
    path = Path(name)
    assert not path.is_absolute() and '..' not in path.parts
    old = (R/path).read_text(); assert hashlib.sha256(old.encode()).hexdigest() == spec['before'], name
    lines = old.splitlines(True); end = len(lines)
    for first, stop, replacement in reversed(spec['edits']):
        assert 0 <= first <= stop <= end
        lines[first:stop] = replacement.splitlines(True); end = first
    new = ''.join(lines); assert hashlib.sha256(new.encode()).hexdigest() == spec['after'], name
    pending[path] = new
    patch += ''.join(difflib.unified_diff(old.splitlines(True), lines, fromfile='a/'+name, tofile='b/'+name))
for path, text in pending.items(): (R/path).write_text(text)
(R/'4.6.4.1-to-4.6.4.2.patch').write_text(patch)
print('Applied and fingerprint-verified', len(pending), 'speed-only source/support files.')
